                                <Text id="slot-tab-1-6-label" data-oods-component="Text" as="strong" content="Obtained by" />
                                <Text id="slot-tab-1-6-value" data-oods-component="Text">{formatReadOnlyValue(provenanceMethod, "string", false)}</Text>
