                            <Stack id="slot-tab-2-8-read-field" data-oods-component="Stack">
                                <Text id="slot-tab-2-8-label" data-oods-component="Text" as="strong" content="Read from" />
                                <Text id="slot-tab-2-8-value" data-oods-component="Text">{formatReadOnlyValue(provenanceLocator, "string", false)}</Text>
