                                <Text id="detail-tabs-9-pass_count-label" data-oods-component="Text" as="strong" content="Pass count" />
                                <Text id="detail-tabs-9-pass_count-value" data-oods-component="Text">{formatReadOnlyValue(passCount, "integer", false)}</Text>
                              </Stack>
                            <Stack id="detail-tabs-9-passes_failed-read-field" data-oods-component="Stack">
                                <Text id="detail-tabs-9-passes_failed-label" data-oods-component="Text" as="strong" content="Passes failed" />
                                <Text id="detail-tabs-9-passes_failed-value" data-oods-component="Text">{formatReadOnlyValue(passesFailed, "integer", false)}</Text>
                              </Stack>
                            <Stack id="detail-tabs-9-artifact_count-read-field" data-oods-component="Stack">
                                <Text id="detail-tabs-9-artifact_count-label" data-oods-component="Text" as="strong" content="Artifact count" />
                                <Text id="detail-tabs-9-artifact_count-value" data-oods-component="Text">{formatReadOnlyValue(artifactCount, "integer", false)}</Text>
                              </Stack>
                            <Stack id="detail-tabs-9-evidence_retained-read-field" data-oods-component="Stack">
                                <Text id="detail-tabs-9-evidence_retained-label" data-oods-component="Text" as="strong" content="Evidence retained" />
                                <Text id="detail-tabs-9-evidence_retained-value" data-oods-component="Text">{formatReadOnlyValue(evidenceRetained, "boolean", false)}</Text>
                              </Stack>
                          </Stack>
                        ) }
                      ]} />
                    </Card>
            </Stack>
        <div role="group" aria-label="Screen actions" data-oods-screen-actions="screen-detail-13">
          <button type="button" data-oods-action="handleDelete" onClick={() => handleDelete()}>Delete</button>
          <button type="button" data-oods-action="handleEdit" onClick={() => handleEdit()}>Edit</button>
        </div>
      </>
    </main>
  );
};
